Ext.define('BNK.view.common.NoticeBoardManagementDetailPopupMViewController', {
    extend: 'BaseViewController',
    alias: 'controller.NoticeBoardManagementDetailPopupMViewController',

    config: {
        viewId: 'NoticeBoardManagementDetailPopupM'
    },

    onPreviousTap: function(button, e, eOpts) {
        var me = this;
        var refs = me.getReferences();
        var vm =me.getViewModel();

        me.getView().fireEvent('onPrevious', me.getView());

    },

    onCloseTap: function(button, e, eOpts) {
        this.getView().close();	// 뒤로가기
    },

    initialize: function(component, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences();

        var noticeData = component.initialConfig.records;

        //<이미지 태그 관련 로직>
        //서버에서 전달해주는 상대주소를 사용 시, 현재 웹 주소에서 경로를 찾는 문제가 있어
        //Property에 저장된 서버 주소를 결합하여 이미지를 찾도록 수정
        var contentHtml = document.createElement('div');
        contentHtml.innerHTML = noticeData.content;

        var imgList = contentHtml.getElementsByTagName('img'); //img태그 collection
        for(var i = 0; i < imgList.length; i++) {
            //서버주소 + 상대주소
            imgList[i].setAttribute('src', Property.BASE_URL + imgList[i].getAttribute('src'));
        }

        refs.title.setHtml(noticeData.subject);
        refs.regDt.setHtml(noticeData.regDt);
        refs.content.setHtml(contentHtml);

    }

});